#include "simulation.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
void quad(Geometry&g,Vec a,Vec b,Vec c,Vec d){Mesh m;m.vertices={{a},{b},{c},{d}};m.indices={0,1,2,0,2,3};g.meshes.push_back(m);}
Geometry road(float step=0,bool wall=false,bool rough=false){Geometry g;g.materials.push_back({"road"});float previous=0;for(int i=-20;i<150;i++){float z=float(i),h=rough&&i>=6&&i<50?(i%2?.025f:0):i>=10?step:0;quad(g,{-50,h,z},{-50,h,z+1},{50,h,z+1},{50,h,z});if(i>-20&&h!=previous)quad(g,{-50,previous,z},{50,previous,z},{50,h,z},{-50,h,z});previous=h;}if(wall)quad(g,{-50,0,10},{50,0,10},{50,3,10},{-50,3,10});return g;}
VehicleConfig car(){VehicleConfig c;c.mass=1000;c.inertia={1100,1200,250};c.lo={-.65f,.10f,-1.5f};c.hi={.65f,.7f,1.5f};c.center_mass={0,.28f,0};c.engine_torque=180;c.ratios={3,2,1.5f,1};c.torque_curve={{950,1},{7000,1}};for(int i=0;i<4;i++){auto&w=c.wheels[i];w.mount={i%2?.75f:-.75f,.15f,i<2?1.15f:-1.15f};w.rest=.32f;w.min=.05f;w.max=.55f;w.radius=.305f;w.k=22000;w.bump=1500;w.rebound=1800;}return c;}
struct Run{float z=0,speed=0,max_drop=0,roll=0,damage=0;};
Run drive(const Geometry&g,const VehicleConfig&c,float spawn_height=1){Simulation s(g,c,translate({0,spawn_height,0}));for(int i=0;i<300;i++)s.step({});float before=0;Run out;for(int i=0;i<700;i++){Input in;in.throttle=1;s.step(in);auto p=s.state();out.max_drop=std::max(out.max_drop,before-p.speed);before=p.speed;out.roll=std::max(out.roll,std::abs(direction(p.car,{0,1,0}).x));}auto p=s.state();out.z=p.car[14];out.speed=p.speed;out.damage=p.damage;return out;}
float weather_stop(const VehicleConfig&c,float grip){Simulation s(road(),c,translate({0,1,0}));s.set_grip_scale(grip);for(int i=0;i<300;++i)s.step({});Input in;in.throttle=1;for(int i=0;i<1500&&s.state().speed<12;++i)s.step(in);need(s.state().speed>=12,"matched-speed weather braking setup must reach 12m/s");float start=s.state().car[14];in={};in.brake=1;for(int i=0;i<400&&s.state().speed>.1f;++i)s.step(in);need(std::abs(s.state().speed)<.5f,"wet and dry brakes must stop without reverse propulsion");return s.state().car[14]-start;}
int main(int argc,char**argv){try{auto c=car();if(argc>1){Resources r(argv[1]);c=load_vehicle(r,3,argc>2?argv[2]:"");}auto flat=drive(road(),c),curb=drive(road(.08f),c),rough=drive(road(0,false,true),c),wall=drive(road(0,true),c);for(auto p:{std::pair<const char*,Run>{"flat",flat},{"curb8cm",curb},{"rough2.5cm",rough},{"wall",wall}})std::cout<<p.first<<" z="<<p.second.z<<" speed="<<p.second.speed<<" drop="<<p.second.max_drop<<" damage="<<p.second.damage<<" roll="<<p.second.roll<<'\n';
 auto raised=road();for(auto&m:raised.meshes)for(auto&v:m.vertices)v.position.y+=5;auto reversed=raised;for(auto&m:reversed.meshes)for(size_t i=0;i<m.indices.size();i+=3)std::swap(m.indices[i+1],m.indices[i+2]);auto up=drive(raised,c,6),down=drive(reversed,c,6);std::cout<<"elevated winding forward="<<up.z<<" reverse="<<down.z<<" roll="<<down.roll<<'\n';need(std::abs(up.z-down.z)<std::max(2.f,up.z*.08f)&&down.roll<.2f,"reversed triangle winding on raised road must not change force lever arm");
 need(curb.z>flat.z*.75f&&curb.max_drop<5,"8cm curb must roll over without a large snag impulse");need(rough.z>flat.z*.8f&&rough.max_drop<4,"small repeated road seams must not stop the vehicle");need(wall.z<12&&wall.damage>0,"real wall remains collidable and damaging");
 Simulation turn(road(),c,translate({0,1,0}));for(int i=0;i<300;i++)turn.step({});Input in;in.steer=1;turn.step(in);std::cout<<"first steering delta="<<turn.state().steer<<'\n';need(std::abs(turn.state().steer)<.08f,"full keyboard steer must build progressively, not snap in one step");
 for(int i=0;i<100;i++)turn.step(in);in.steer=0;for(int i=0;i<100;i++)turn.step(in);need(std::abs(turn.state().steer)<.001f,"steering returns smoothly to center");
 Simulation braking(road(),c,translate({0,1,0}));for(int i=0;i<300;i++)braking.step({});in={};in.throttle=1;for(int i=0;i<400;i++)braking.step(in);float start_speed=braking.state().speed,start_z=braking.state().car[14];in={};in.brake=1;for(int i=0;i<250;i++)braking.step(in);std::cout<<"braking start="<<start_speed<<" end="<<braking.state().speed<<" distance="<<braking.state().car[14]-start_z<<'\n';need(std::abs(braking.state().speed)<2,"normal brakes must stop within 2.5 seconds from this acceleration test");need(braking.state().speed>-.5f,"brakes must not create reverse propulsion");
 Simulation corner(road(),c,translate({0,1,0}));for(int i=0;i<300;i++)corner.step({});in={};in.throttle=1;float min_up=1;for(int i=0;i<600;i++){in.steer=i>200?.22f:0;corner.step(in);min_up=std::min(min_up,direction(corner.state().car,{0,1,0}).y);}auto end=corner.state();std::cout<<"power corner x="<<end.car[12]<<" z="<<end.car[14]<<" speed="<<end.speed<<" up="<<min_up<<'\n';need(end.car[12]>4&&end.speed>4&&min_up>.5f,"powered corner must turn predictably without rollover or spin-stall");
 float dry_stop=weather_stop(c,1),wet_stop=weather_stop(c,.92f);std::cout<<"matched 12m/s dry stop="<<dry_stop<<" wet stop="<<wet_stop<<'\n';need(wet_stop>dry_stop*1.03f,"rain friction reduction must lengthen a friction-limited stop");
 std::cout<<"track contact, progressive steering, braking and powered corner passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
